for n,title,standard in [(154,'Salsa Rizada Económica (Pale Meat and Mushroom Sauce)',False),(155,'Salsa Rizada (Pale Chicken, Beef and Mushroom Sauce)',True)]:
 items=[I('beef',500 if standard else 1360,'g','food-grade beef shin pieces, trimmed of excess fat','Use the same weight of beef chuck; simmer until tender.'),carrot(200),onion(200),I('scallion',30,'g','scallions, rinsed','Use the same weight of trimmed leek.'),parsley(10),I('cloves',2 if standard else 3,'','whole cloves','Omit for a milder sauce.'),water(2500 if not standard else 500),butter(80),flour(80),I('mushroom',200,'g','cultivated white mushrooms, sliced','Use the same weight of cultivated cremini mushrooms.'),salt(5)]
 if standard:items += [I('chicken',1500,'g','raw bone-in chicken pieces','Use the same weight of bone-in turkey pieces, cooking until tender and at least 74°C (165°F).'),dict(stock(2000),name='unsalted prepared chicken stock'),lemon(15)]
 else:items += [I('bay',3,'','dried bay leaves','Omit if unavailable.')]
 first='Put {{beef}}'+(' and {{chicken}}' if standard else '')+' in a large stockpot with {{carrot}} cut in chunks, quartered {{onion}}, {{scallion}}, {{parsley}} and {{cloves}}'+(' and {{bay}}' if not standard else '')+'. Add {{water}}'+(' and {{stock}}' if standard else '')+'. Bring slowly to a simmer, skimming foam.'
 steps=[first,'Simmer gently, partly covered, for '+('2–2½ hours' if standard else '2 hours')+', adding water if needed to keep the meat covered. '+('Lift out the chicken as soon as it is tender and reaches 74°C (165°F) in the thickest flesh away from bone, usually after 45–75 minutes; continue cooking the beef until tender.' if standard else 'Continue until the beef is tender. Do not brown the ingredients.'),'Strain the broth through a fine sieve into a bowl. Reserve the cooked meat for another meal, removing any bones; cool promptly in shallow containers and refrigerate within 2 hours. Discard the spent vegetables and whole spices.','In a clean heavy saucepan, melt {{butter}}, stir in {{flour}} and cook for 2 minutes without coloring. Add {{mushroom}}'+(' and {{lemon}}' if standard else '')+' and stir over low heat for 5 minutes.','Gradually whisk in the strained broth and add {{salt}}. Simmer very gently, uncovered, for 90 minutes, stirring frequently and skimming surface fat. Add water if it becomes too thick or begins to catch.','Pass through a fine sieve, pressing gently, and discard the mushroom solids. The finished sauce should lightly coat a spoon; loosen with a little hot water if needed. Serve immediately, or cool promptly and refrigerate.']
 r=add(n,title,16,285 if standard else 250,'A pale mushroom roux thickens a slowly prepared '+('chicken-and-beef' if standard else 'beef')+' broth into a smooth savory sauce.',items,steps,('A smaller domestic batch uses one chicken and beef shin in place of the much larger source chicken/shank preparation. Prepared unsalted stock replaces undefined concentrated broth. The stock is cooked and strained before thickening, rather than simmering raw poultry in thick sauce.' if standard else 'The source three pounds of meat becomes 1360 g beef shin, using fresh food-grade meat rather than unspecified leftovers. The modern stock starts with measured water instead of allowing the pot to cook nearly dry.')+' Missing vegetable, liquid and roux quantities are supplied. The sauce contains no cream; the English creamed label is corrected. Yield is approximately sixteen small sauce portions and varies with reduction. Not shelf-stable.','Sauces')
 r['source']+=' Cooking-temperature reference: https://www.foodsafety.gov/food-safety-charts/safe-minimum-internal-temperatures'
r=add(156,"Maître d’Hôtel Sauce with Lemon and Egg Yolk",6,25,'A light consommé sauce is enriched with butter, parsley, lemon and a gently cooked egg yolk.',[butter(14),flour(8),dict(stock(480),name='unsalted prepared beef consommé'),lemon(15),parsley(5),yolks(1)],['Melt {{butter}} in a saucepan, stir in {{flour}} and cook for 2 minutes without browning. Gradually whisk in {{stock}}.','Add {{lemon}} and {{parsley}} and simmer gently for 15 minutes, stirring.','Whisk {{yolks}} in a bowl. Gradually whisk in a little hot sauce, then return to the saucepan. Stir over low heat until the sauce reaches 71°C (160°F), without boiling. Serve immediately.'],'The source pint becomes a modern 480 ml and half a lemon becomes 15 ml. Controlled egg heating replaces the raw off-heat finish. This source sauce includes stock, flour and egg, and is distinct from parsley-lemon compound butter.','Sauces')
r=add(157,'Butter-Sauce (Light Beef-Stock Roux Sauce)',6,15,'A pale butter-and-flour roux is whisked with beef stock and simmered into a smooth sauce for vegetables.',[butter(40),flour(40),dict(stock(500),name='unsalted prepared light beef stock')],['Melt {{butter}} over low heat. Stir in {{flour}} and cook for 2 minutes without browning.','Gradually whisk in {{stock}} until smooth. Bring to a gentle simmer and cook for 5–7 minutes, stirring constantly. Pass through a fine sieve if needed and serve.'],'The extraction lists eight ounces each of butter and flour for 500 ml broth, which would make an unusually thick paste. This adaptation deliberately uses 40 g each for a pourable sauce; these are modern formula choices, not a claim about the original units.','Sauces')
for n,title,b,f,wat in [(158,'Melted or Drawn Butter Sauce No. 1',43,5,180),(159,'Melted or Drawn Butter Sauce No. 2',57,4,150)]:
 items=[flour(f),water(wat),butter(b)]+([salt(.5)] if n==158 else [])
 steps=['Whisk {{flour}}'+(' and {{salt}}' if n==158 else '')+' into {{water}} a little at a time in a small saucepan, making a smooth mixture.','Heat gently, whisking, until it simmers. Continue for 2–3 minutes to cook the flour.','Reduce the heat and whisk in {{butter}} in small pieces until smooth. Simmer very gently for 1 minute while stirring, then serve.']
 r=add(n,title,4,15,'A small amount of flour holds melted butter in a smooth '+('lightly salted' if n==158 else 'rich')+' sauce.',items,steps,'The source butter weight is rounded to modern grams. Its undefined '+('teacup' if n==158 else 'small teacup')+' becomes '+str(wat)+' ml. A controlled low-heat saucepan replaces the nested boiling-water vessel so the flour can cook predictably.','Sauces')
 if n==158:variant(r,'milk','Milk-based drawn butter',[dict(i,name='whole milk',substitution='Use the water base for a lighter sauce.') if i['key']=='water' else copy.deepcopy(i) for i in r['ingredients']],copy.deepcopy(r['steps']))
r=add(160,'Melted or Drawn Butter Sauce No. 3 with Egg',6,20,'Butter is whisked into a lightly thickened sauce, then enriched with a tempered whole egg.',[butter(85),water(240),I('egg',1,'','large pasteurized egg','Use 50 g pasteurized liquid whole egg.'),flour(4),milk(30)],['Whisk {{flour}} into {{milk}} until smooth. Heat {{water}} in a saucepan, whisk in the slurry and simmer for 2–3 minutes.','Beat {{egg}} in a bowl. Gradually whisk in a few spoonfuls of the hot thickened liquid.','Reduce the saucepan to low heat and whisk in {{butter}} in small pieces. Slowly stir in the tempered egg mixture and continue stirring until it reaches 71°C (160°F), without boiling. Serve immediately.'],'The source half-pint becomes a modern 240 ml and missing slurry milk becomes 30 ml. Low controlled heat replaces an unspecified nested pan, and the egg finish is explicitly cooked.','Sauces')
